<script setup lang="ts">
import{computed,onMounted,reactive,ref,watch}from'vue';import NxAlert from'../../components/ui/NxAlert.vue';import NxBadge from'../../components/ui/NxBadge.vue';import NxButton from'../../components/ui/NxButton.vue';import NxCard from'../../components/ui/NxCard.vue';import NxModal from'../../components/ui/NxModal.vue';import NxPageHeader from'../../components/ui/NxPageHeader.vue';import NxTableShell from'../../components/ui/NxTableShell.vue';import NxToolbar from'../../components/ui/NxToolbar.vue';import{get,items,post,type Row}from'./api';
type Tab='overview'|'invoices'|'payments'|'adjustments'|'collections'|'runs'|'settings';const tab=ref<Tab>('overview'),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),overview=ref<Row>({}),invoices=ref<Row[]>([]),payments=ref<Row[]>([]),adjustments=ref<Row[]>([]),collections=ref<Row[]>([]),runs=ref<Row[]>([]),services=ref<Row[]>([]),settings=reactive<Row>({}),modal=ref<'invoice'|'payment'|'adjustment'|'detail'|null>(null),detail=ref<any>(null);
const invoiceForm=reactive<Row>({service_id:'',billing_period_start:'',billing_period_end:'',issue_date:'',due_date:'',description:'',quantity:1,unit_price:0,discount_amount:0,tax_amount:0,notes:''}),paymentForm=reactive<Row>({invoice_id:'',amount:0,method:'CASH',payment_date:'',reference_no:'',remarks:''}),adjustmentForm=reactive<Row>({invoice_id:'',adjustment_type:'CREDIT',amount:0,reason:''});
const money=(v:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(v||0));const fmt=(v:any)=>v?new Date(String(v).replace(' ','T')).toLocaleDateString('en-PH'):'—';const status=(r:Row)=>String(r.payment_status||r.status||'UNKNOWN').toUpperCase();const tone=(v:any):'success'|'danger'|'warning'|'neutral'=>['PAID','POSTED','SUCCESS','COMPLETED'].includes(String(v).toUpperCase())?'success':['CANCELLED','VOID','VOIDED','FAILED','REJECTED'].includes(String(v).toUpperCase())?'danger':['PENDING','OVERDUE','RUNNING'].includes(String(v).toUpperCase())?'warning':'neutral';const rows=computed(()=>tab.value==='invoices'?invoices.value:tab.value==='payments'?payments.value:tab.value==='adjustments'?adjustments.value:tab.value==='collections'?collections.value:tab.value==='runs'?runs.value:[]);const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return rows.value.filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q));});const inputClass='min-h-11 w-full rounded-md border border-[var(--nx-border)] bg-[var(--nx-surface)] px-3 text-[var(--nx-text)]';
async function loadAll(show=false){loading.value=true;error.value='';try{const[o,i,p,a,c,r,s,sv]=await Promise.all([get('/api/v1/billing/overview'),get('/api/v1/billing/invoices/list'),get('/api/v1/billing/payments/list'),get('/api/v1/billing/adjustments/list'),get('/api/v1/billing/collections/aging'),get('/api/v1/billing/runs/list'),get('/api/v1/billing/settings'),get('/api/v1/billing/support/services')]);overview.value=o||{};invoices.value=items(i);payments.value=items(p);adjustments.value=items(a);collections.value=items(c);runs.value=items(r);services.value=items(sv);Object.assign(settings,(s as any)?.map||s||{});if(show)notice.value='Billing data refreshed.';}catch(e){error.value=e instanceof Error?e.message:'Unable to load billing data.';}finally{loading.value=false;}}
function openForm(kind:'invoice'|'payment'|'adjustment',invoice?:Row){const now=new Date(),day=now.toISOString().slice(0,10);if(kind==='invoice'){invoiceForm.issue_date=invoiceForm.billing_period_start=day;invoiceForm.billing_period_end=new Date(now.getTime()+29*864e5).toISOString().slice(0,10);invoiceForm.due_date=new Date(now.getTime()+10*864e5).toISOString().slice(0,10);}if(invoice){paymentForm.invoice_id=adjustmentForm.invoice_id=invoice.id;paymentForm.amount=Number(invoice.balance_amount||0);}paymentForm.payment_date=new Date().toISOString().slice(0,16);modal.value=kind;}
async function saveForm(){busy.value=true;error.value='';try{if(modal.value==='invoice'){const payload={...invoiceForm,items:invoiceForm.description||Number(invoiceForm.unit_price)>0?[{item_type:'PLAN',description:invoiceForm.description||'Monthly internet service',quantity:Number(invoiceForm.quantity),unit_price:Number(invoiceForm.unit_price)}]:undefined};await post('/api/v1/billing/invoices/create',payload);notice.value='Invoice created.';}else if(modal.value==='payment'){await post('/api/v1/billing/payments/create',{...paymentForm,payment_date:String(paymentForm.payment_date).replace('T',' ')+':00'});notice.value='Payment recorded.';}else{await post('/api/v1/billing/adjustments/create',adjustmentForm);notice.value='Adjustment posted.';}modal.value=null;await loadAll();}catch(e){error.value=e instanceof Error?e.message:'Unable to save billing record.';}finally{busy.value=false;}}
async function show(row:Row){busy.value=true;try{const base=['invoices','collections'].includes(tab.value)?'invoices/show':tab.value==='payments'?'payments/show':tab.value==='adjustments'?'adjustments/show':'runs/show';detail.value=await get(`/api/v1/billing/${base}/${row.id}`);modal.value='detail';}catch(e){error.value=e instanceof Error?e.message:'Unable to load details.';}finally{busy.value=false;}}
async function action(url:string,message:string,reason=false){const why=reason?prompt('Reason is required:'):'';if(reason&&!why)return;if(!reason&&!confirm(message+'?'))return;busy.value=true;try{await post(url,reason?{reason:why}:{});notice.value=message+' completed.';await loadAll();}catch(e){error.value=e instanceof Error?e.message:'Billing action failed.';}finally{busy.value=false;}}
async function generate(){await action('/api/v1/billing/generate-due-invoices','Generate due invoices');tab.value='runs';}async function saveSettings(){busy.value=true;try{await post('/api/v1/billing/settings/save',{...settings,tax_enabled:settings.tax_enabled?1:0,auto_suspend_enabled:settings.auto_suspend_enabled?1:0});notice.value='Billing settings saved.';}catch(e){error.value=e instanceof Error?e.message:'Unable to save settings.';}finally{busy.value=false;}}
watch(tab,()=>{error.value='';notice.value='';});watch(()=>settings.tax_enabled,v=>{if(v==='0')settings.tax_enabled=false;if(v==='1')settings.tax_enabled=true;});watch(()=>settings.auto_suspend_enabled,v=>{if(v==='0')settings.auto_suspend_enabled=false;if(v==='1')settings.auto_suspend_enabled=true;});onMounted(()=>void loadAll());
</script>
<template><div class="space-y-4 overflow-x-hidden pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="Finance operations · PHP · Asia/Manila" title="Billing Center" description="Invoices, collections, adjustments, payments, and scheduled billing runs."><template #actions><NxButton variant="secondary" :disabled="loading||busy" @click="loadAll(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton><NxButton variant="secondary" :disabled="busy" @click="generate">Generate Due Invoices</NxButton><NxButton :disabled="busy" @click="openForm('invoice')">New Invoice</NxButton><NxButton variant="secondary" :disabled="busy" @click="openForm('payment')">Record Payment</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert>
<section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="card in [['Total Billed',overview.stats?.total_billed,'All non-cancelled invoices'],['Collected',overview.stats?.total_collected,'Posted payments'],['Outstanding',overview.stats?.total_balance,'Remaining balance'],['Overdue',overview.stats?.overdue_invoices,'Invoices past due']]" :key="String(card[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{card[0]}}</p><p class="mt-2 text-2xl font-bold">{{card[0]==='Overdue'?card[1]||0:money(card[1])}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{card[2]}}</p></NxCard></section>
<NxToolbar><div class="flex flex-col gap-3 xl:flex-row xl:items-center xl:justify-between"><div class="flex flex-wrap gap-2" role="tablist"><button v-for="t in [['overview','Overview'],['invoices','Invoices'],['payments','Payments'],['adjustments','Adjustments'],['collections','Collections'],['runs','Billing Runs'],['settings','Settings']]" :key="t[0]" class="min-h-10 rounded-md px-3 text-sm font-semibold" :class="tab===t[0]?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="tab=t[0] as Tab">{{t[1]}}</button></div><input v-if="!['overview','settings'].includes(tab)" v-model="search" type="search" placeholder="Search billing records…" :class="inputClass+' xl:w-80'"></div></NxToolbar>
<div v-if="tab==='overview'" class="grid gap-4 xl:grid-cols-2"><NxCard title="Recent Invoices" description="Latest subscriber charges"><div class="space-y-3"><button v-for="r in (overview.recent_invoices||[])" :key="r.id" class="flex w-full items-center justify-between rounded-md bg-[var(--nx-surface-muted)] p-3 text-left" @click="tab='invoices';show(r)"><span><b>{{r.invoice_no}}</b><small class="block text-[var(--nx-text-muted)]">{{r.subscriber_name}} · Due {{fmt(r.due_date)}}</small></span><b>{{money(r.balance_amount)}}</b></button><p v-if="!overview.recent_invoices?.length" class="py-8 text-center text-[var(--nx-text-muted)]">No invoices yet.</p></div></NxCard><NxCard title="Recent Payments" description="Latest posted and pending receipts"><div class="space-y-3"><button v-for="r in (overview.recent_payments||[])" :key="r.id" class="flex w-full items-center justify-between rounded-md bg-[var(--nx-surface-muted)] p-3 text-left" @click="tab='payments';show(r)"><span><b>{{r.payment_no}}</b><small class="block text-[var(--nx-text-muted)]">{{r.subscriber_name}} · {{r.method}}</small></span><b>{{money(r.amount)}}</b></button><p v-if="!overview.recent_payments?.length" class="py-8 text-center text-[var(--nx-text-muted)]">No payments yet.</p></div></NxCard></div>
<NxCard v-else-if="tab==='settings'" title="Billing Settings" description="Numbering, due dates, tax, and service automation"><form id="billing-settings-form" class="grid gap-4 md:grid-cols-2 xl:grid-cols-3" @submit.prevent="saveSettings"><label v-for="f in [['invoice_prefix','Invoice Prefix'],['payment_prefix','Payment Prefix'],['adjustment_prefix','Adjustment Prefix'],['currency','Currency'],['default_due_days','Default Due Days'],['grace_period_days','Grace Period Days'],['tax_rate','Tax Rate']]" :key="f[0]" class="grid gap-2 text-sm font-semibold">{{f[1]}}<input v-model="settings[f[0]]" :type="String(f[0]).includes('days')||f[0]==='tax_rate'?'number':'text'" :class="inputClass"></label><label class="flex items-center gap-3"><input v-model="settings.tax_enabled" type="checkbox">Enable tax</label><label class="flex items-center gap-3"><input v-model="settings.auto_suspend_enabled" type="checkbox">Automatically suspend overdue service</label><div class="flex justify-end md:col-span-2 xl:col-span-3"><NxButton type="submit" :disabled="busy">Save Settings</NxButton></div></form></NxCard>
<NxCard v-else><div class="flex items-center justify-between border-b border-[var(--nx-border)] p-5"><div><h2 class="font-bold capitalize">{{tab}}</h2><p class="text-sm text-[var(--nx-text-muted)]">{{filtered.length}} records</p></div><div class="flex gap-2"><NxButton v-if="tab==='invoices'" @click="openForm('invoice')">New Invoice</NxButton><NxButton v-if="tab==='payments'" @click="openForm('payment')">Record Payment</NxButton><NxButton v-if="tab==='adjustments'" @click="openForm('adjustment')">New Adjustment</NxButton></div></div><NxTableShell min-width="1050px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase"><tr><th class="px-4 py-3">Reference</th><th class="px-4 py-3">Subscriber</th><th class="px-4 py-3">Invoice / Service</th><th class="px-4 py-3">Date</th><th class="px-4 py-3 text-right">Amount</th><th class="px-4 py-3">Status</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!filtered.length"><td colspan="7" class="px-4 py-12 text-center text-[var(--nx-text-muted)]">No records found.</td></tr><tr v-for="r in filtered" :key="r.id"><td class="px-4 py-3 font-bold">{{r.invoice_no||r.payment_no||r.adjustment_no||r.run_no||`#${r.id}`}}</td><td class="px-4 py-3">{{r.subscriber_name||'—'}}<small class="block text-[var(--nx-text-muted)]">{{r.account_number||''}}</small></td><td class="px-4 py-3">{{r.invoice_no||r.plan_name||r.run_type||'—'}}<small class="block text-[var(--nx-text-muted)]">{{r.service_number||r.aging_bucket_label||''}}</small></td><td class="px-4 py-3">{{fmt(r.payment_date||r.due_date||r.created_at||r.started_at)}}</td><td class="px-4 py-3 text-right font-semibold">{{money(r.balance_amount??r.amount??r.total_amount??0)}}</td><td class="px-4 py-3"><NxBadge :tone="tone(status(r))">{{status(r)}}</NxBadge></td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton variant="secondary" @click="show(r)">View</NxButton><a v-if="tab==='invoices'" :href="`/billing/invoices/print/${r.id}`" target="_blank" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] px-3 text-sm font-semibold text-[var(--nx-text)] no-underline">Print</a><NxButton v-if="tab==='invoices'&&Number(r.balance_amount)>0&&status(r)!=='CANCELLED'" @click="openForm('payment',r)">Pay</NxButton><NxButton v-if="tab==='payments'&&status(r)==='PENDING'" variant="secondary" @click="action(`/api/v1/billing/payments/${r.id}/approve`,'Approve payment')">Approve</NxButton><NxButton v-if="tab==='payments'&&status(r)==='PENDING'" variant="danger" @click="action(`/api/v1/billing/payments/${r.id}/reject`,'Reject payment',true)">Reject</NxButton><NxButton v-if="tab==='payments'&&status(r)==='POSTED'" variant="danger" @click="action(`/api/v1/billing/payments/void/${r.id}`,'Void payment',true)">Void</NxButton></div></td></tr></tbody></NxTableShell></NxCard>
<NxModal :open="modal==='invoice'" title="Create Invoice" description="Create a subscriber service invoice." max-width="54rem" @close="modal=null"><form id="invoice-form" class="grid gap-4 p-6 md:grid-cols-2" @submit.prevent="saveForm"><label class="grid gap-2 text-sm font-semibold md:col-span-2">Subscriber Service<select v-model="invoiceForm.service_id" required :class="inputClass"><option value="">Select service</option><option v-for="r in services" :key="r.id" :value="r.id">{{r.subscriber_name}} · {{r.plan_name}} · {{r.service_number||r.id}}</option></select></label><label v-for="f in [['billing_period_start','Period Start','date'],['billing_period_end','Period End','date'],['issue_date','Issue Date','date'],['due_date','Due Date','date'],['description','Item Description','text'],['quantity','Quantity','number'],['unit_price','Unit Price','number'],['discount_amount','Discount','number'],['tax_amount','Tax','number']]" :key="f[0]" class="grid gap-2 text-sm font-semibold">{{f[1]}}<input v-model="invoiceForm[f[0]]" :type="f[2]" :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold md:col-span-2">Notes<textarea v-model="invoiceForm.notes" :class="inputClass"></textarea></label></form><template #footer><NxButton variant="secondary" @click="modal=null">Cancel</NxButton><NxButton type="submit" form="invoice-form" :disabled="busy">Create Invoice</NxButton></template></NxModal>
<NxModal :open="modal==='payment'" title="Record Payment" description="Post a received payment against an invoice." max-width="48rem" @close="modal=null"><form id="payment-form" class="grid gap-4 p-6 md:grid-cols-2" @submit.prevent="saveForm"><label class="grid gap-2 text-sm font-semibold md:col-span-2">Invoice<select v-model="paymentForm.invoice_id" required :class="inputClass"><option value="">Select invoice</option><option v-for="r in invoices.filter(x=>Number(x.balance_amount)>0&&status(x)!=='CANCELLED')" :key="r.id" :value="r.id">{{r.invoice_no}} · {{r.subscriber_name}} · {{money(r.balance_amount)}}</option></select></label><label class="grid gap-2 text-sm font-semibold">Amount<input v-model.number="paymentForm.amount" type="number" step=".01" required :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold">Method<select v-model="paymentForm.method" :class="inputClass"><option>CASH</option><option>BANK_TRANSFER</option><option>GCASH</option><option>MAYA</option><option>CHECK</option></select></label><label class="grid gap-2 text-sm font-semibold">Payment Date<input v-model="paymentForm.payment_date" type="datetime-local" :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold">Reference Number<input v-model="paymentForm.reference_no" :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold md:col-span-2">Remarks<textarea v-model="paymentForm.remarks" :class="inputClass"></textarea></label></form><template #footer><NxButton variant="secondary" @click="modal=null">Cancel</NxButton><NxButton type="submit" form="payment-form" :disabled="busy">Post Payment</NxButton></template></NxModal>
<NxModal :open="modal==='adjustment'" title="Create Adjustment" description="Post a credit, debit, correction, rebate, or waiver." max-width="48rem" @close="modal=null"><form id="adjustment-form" class="grid gap-4 p-6 md:grid-cols-2" @submit.prevent="saveForm"><label class="grid gap-2 text-sm font-semibold md:col-span-2">Invoice<select v-model="adjustmentForm.invoice_id" required :class="inputClass"><option value="">Select invoice</option><option v-for="r in invoices.filter(x=>status(x)!=='CANCELLED')" :key="r.id" :value="r.id">{{r.invoice_no}} · {{r.subscriber_name}}</option></select></label><label class="grid gap-2 text-sm font-semibold">Type<select v-model="adjustmentForm.adjustment_type" :class="inputClass"><option>CREDIT</option><option>DEBIT</option><option>DISCOUNT</option><option>REBATE</option><option>WAIVER</option><option>CORRECTION</option></select></label><label class="grid gap-2 text-sm font-semibold">Amount<input v-model.number="adjustmentForm.amount" type="number" step=".01" required :class="inputClass"></label><label class="grid gap-2 text-sm font-semibold md:col-span-2">Reason<textarea v-model="adjustmentForm.reason" required :class="inputClass"></textarea></label></form><template #footer><NxButton variant="secondary" @click="modal=null">Cancel</NxButton><NxButton type="submit" form="adjustment-form" :disabled="busy">Post Adjustment</NxButton></template></NxModal>
<NxModal :open="modal==='detail'" title="Billing Record Details" description="Complete API record and related entries." max-width="64rem" @close="modal=null"><pre class="max-h-[60vh] overflow-auto whitespace-pre-wrap p-6 text-xs text-[var(--nx-text)]">{{JSON.stringify(detail,null,2)}}</pre><template #footer><a v-if="detail?.invoice?.id" :href="`/billing/invoices/print/${detail.invoice.id}`" target="_blank" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] px-3 text-sm font-semibold text-[var(--nx-text)] no-underline">Print Invoice</a><NxButton v-if="detail?.invoice?.id&&Number(detail.invoice.balance_amount)>0&&status(detail.invoice)!=='CANCELLED'" @click="modal=null;openForm('payment',detail.invoice)">Record Payment</NxButton><NxButton v-if="detail?.invoice?.id&&status(detail.invoice)!=='CANCELLED'" variant="secondary" @click="modal=null;openForm('adjustment',detail.invoice)">Adjustment</NxButton><NxButton v-if="tab==='invoices'&&detail?.invoice?.id&&!['PAID','CANCELLED'].includes(status(detail.invoice))" variant="danger" @click="action(`/api/v1/billing/invoices/cancel/${detail.invoice.id}`,'Cancel invoice')">Cancel Invoice</NxButton><a v-if="detail?.payment?.id" :href="`/billing/payments/receipt/${detail.payment.id}`" target="_blank" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] px-3 text-sm font-semibold text-[var(--nx-text)] no-underline">Receipt</a><a v-if="detail?.payment?.id&&status(detail.payment)==='PENDING'" :href="`/api/v1/billing/payments/${detail.payment.id}/proof`" target="_blank" class="inline-flex min-h-10 items-center rounded-md border border-[var(--nx-border)] px-3 text-sm font-semibold text-[var(--nx-text)] no-underline">Payment Proof</a><NxButton v-if="detail?.payment?.id&&status(detail.payment)==='PENDING'" @click="action(`/api/v1/billing/payments/${detail.payment.id}/approve`,'Approve payment')">Approve</NxButton><NxButton v-if="detail?.payment?.id&&status(detail.payment)==='PENDING'" variant="danger" @click="action(`/api/v1/billing/payments/${detail.payment.id}/reject`,'Reject payment',true)">Reject</NxButton><NxButton v-if="detail?.payment?.id&&status(detail.payment)==='POSTED'" variant="danger" @click="action(`/api/v1/billing/payments/void/${detail.payment.id}`,'Void payment',true)">Void Payment</NxButton><NxButton v-if="detail?.adjustment?.id&&status(detail.adjustment)==='POSTED'" variant="danger" @click="action(`/api/v1/billing/adjustments/void/${detail.adjustment.id}`,'Void adjustment',true)">Void Adjustment</NxButton><NxButton variant="secondary" @click="modal=null">Close</NxButton></template></NxModal></div></template>
<style scoped>:global([data-nx-next-root="billing"]){max-width:100%;overflow-x:hidden}</style>
